from pathlib import Path
import pymupdf as fitz

MATERIALS = {
"windows_authentication.pdf": """EDUCATIONAL DEMONSTRATION REFERENCE — NOT AUTHENTIC INVESTIGATIVE RECORDS\nWindows authentication and logon forensics\n\nEvent ID 4624 records a successful logon; 4625 records a failed logon; 4672 indicates special privileges assigned to a new logon. Logon type helps characterize context: type 2 is interactive, type 3 network, type 4 batch, type 5 service, type 7 unlock, type 10 remote interactive (commonly Remote Desktop), and type 11 cached interactive. Interpret fields such as account, source address, workstation, authentication package, and logon ID in context and correlate with other records.\n\nLimitations: event collection may be disabled, filtered, overwritten, incomplete, or altered; fields can be absent or environment-specific. A source address may identify an intermediary. Event presence alone does not establish who operated a system or intent. Validate time zones, clock drift, retention, audit policy, and corroborate with independent sources. These are reference examples, not case evidence.\n\nSources: Microsoft Learn, Audit Logon (4624/4625) and Audit Special Logon (4672), Windows security auditing documentation, https://learn.microsoft.com/windows/security/threat-protection/auditing/basic-audit-logon-events and https://learn.microsoft.com/windows/security/threat-protection/auditing/audit-special-logon.""",
"sysmon_process_creation.pdf": """EDUCATIONAL DEMONSTRATION REFERENCE — NOT AUTHENTIC INVESTIGATIVE RECORDS\nSysmon and process-creation analysis\n\nSysmon Event ID 1 records process creation. Depending on configuration and version, fields include image path, command line, parent image and command line, user, hashes, process GUID, and timestamps. Process GUIDs help correlate activity despite PID reuse. Parent-child relationships can reveal unusual execution chains, such as an office application starting a script interpreter, but unusual ancestry is a lead rather than proof of maliciousness.\n\nFor PowerShell, examine full command line and parent context for encoded commands, hidden or non-interactive modes, download or web-request behavior, execution-policy bypass flags, and suspicious script paths. These indicators are not conclusive: administrators and software may use similar options. Preserve original logs and correlate with script block logging, endpoint telemetry, network records, and known-good baselines where available.\n\nLimitations: Sysmon must be installed and configured; exclusions, gaps, tampering, retention, and incomplete command-line capture affect conclusions. Validate timestamps and collection context.\n\nSources: Microsoft Sysmon documentation, https://learn.microsoft.com/sysinternals/downloads/sysmon; Microsoft PowerShell logging documentation, https://learn.microsoft.com/powershell/module/microsoft.powershell.core/about/about_logging.""",
"network_forensics.pdf": """EDUCATIONAL DEMONSTRATION REFERENCE — NOT AUTHENTIC INVESTIGATIVE RECORDS\nNetwork forensics and suspicious connections\n\nSysmon Event ID 3 can record network connections and associate them with process identifiers/GUIDs when network connection logging is enabled. Event ID 22 records DNS queries when configured and supported. Review process identity, destination IP and port, protocol, initiating account, timing, DNS query/response context, and related process-creation events. Compare destinations and timing with expected application behavior and network baselines.\n\nPotential beaconing leads include repeated connections at regular intervals, repeated small transfers, unusual destinations, and recurring DNS lookups. These patterns require context: legitimate health checks, proxies, NAT, CDNs, and scheduled tasks can look similar. Correlate endpoint logs with firewall, proxy, DNS resolver, packet capture, and server-side records when available.\n\nLimitations: events may be disabled, filtered, lost, encrypted, or obscured by proxies, NAT, VPNs, shared hosting, or short retention. DNS caches and resolver logs have different coverage. A connection or domain lookup alone does not prove compromise, data transfer, actor identity, or intent.\n\nSources: Microsoft Sysmon documentation, https://learn.microsoft.com/sysinternals/downloads/sysmon; NIST SP 800-86, Guide to Integrating Forensic Techniques into Incident Response, https://csrc.nist.gov/pubs/sp/800/86/final."""
}

def generate_samples(folder: str | Path) -> list[Path]:
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    paths = []
    for name, text in MATERIALS.items():
        path = folder / name
        if not path.exists():
            doc = fitz.open()
            page = doc.new_page()
            page.insert_textbox(fitz.Rect(55, 55, 540, 760), text, fontsize=10, fontname="helv")
            doc.save(path)
            doc.close()
        paths.append(path)
    return paths
